pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(actor);
        try c.sendTo(address(0xdead), amount) {
            if (actor != address(this)) {
                assertTrue(false);
            }
        } catch {
            // Expected to revert when actor is not the owner and check is present, or when amount > balance
        }
        if (actor == address(this)) {
            assertTrue(address(c).balance < balanceBefore);
        } else {
            assertTrue(address(c).balance == balanceBefore);
        }
    }
}

