pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        // The owner is the setUp EOA (this contract's address); restrict actor to that owner.
        // The property: owner can always send; the bug reverses it, so owner's call reverts.
        address owner = address(this);
        vm.assume(actor == owner);
        vm.deal(actor, amount);
        bool ok;
        vm.prank(actor);
        try c.sendTo(address(0x1), amount) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

