pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address caller) public {
        // Ensure caller is not the zero address (default owner in setUp)
        vm.assume(caller != address(0));
        // Control the caller
        vm.prank(caller);
        // Record whether the call reverts
        bool ok;
        try c.sendTo(address(0x1234), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference reverts iff caller != owner; the buggy reverts iff caller == owner.
        // General rule: (caller == owner) <==> !revert.
        assertTrue(ok == (caller == address(this)));
    }
}
